"""Add `= None` to model fields that were implicitly optional under pydantic v1.

In pydantic v1 a field whose annotation allows None without an explicit default
was not required and defaulted to None. In pydantic v2 such a field is required,
so we must add the explicit default to keep the old behaviour.
"""
import ast
import pathlib
import sys

MODELS = pathlib.Path("cortex_xdr_client/api/models")


def has_none(annotation: ast.expr) -> bool:
    """True if the annotation allows None anywhere (NoneType in flattened union)."""
    if isinstance(annotation, ast.Name) and annotation.id in ("None", "NoneType"):
        return True
    if isinstance(annotation, ast.Constant) and annotation.value is None:
        return True
    if isinstance(annotation, ast.Subscript):
        if has_none(annotation.value):  # Optional itself is not a name with None
            return True
        return has_none(annotation.slice)
    if isinstance(annotation, ast.Tuple):
        return any(has_none(e) for e in annotation.elts)
    return False


def model_classes(tree: ast.Module):
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef):
            bases = {ast.unparse(b) for b in node.bases}
            if bases & {"BaseModel"} or any(b.startswith("RootModel") for b in bases):
                yield node


changed_total = 0
for path in sorted(MODELS.glob("*.py")):
    source = path.read_text(encoding="utf-8")
    tree = ast.parse(source)
    lines = source.splitlines(keepends=True)
    targets = []  # (lineno, field name)
    for cls in model_classes(tree):
        for stmt in cls.body:
            if not isinstance(stmt, ast.AnnAssign):
                continue
            if not isinstance(stmt.target, ast.Name):
                continue
            if stmt.value is not None:
                continue
            if not has_none(stmt.annotation):
                continue
            if stmt.end_lineno != stmt.lineno:
                print(f"SKIP multi-line annotation in {path}:{stmt.lineno}")
                continue
            targets.append((stmt.lineno, stmt.target.id))
    if not targets:
        continue
    for lineno, name in sorted(targets, reverse=True):
        line = lines[lineno - 1]
        stripped = line.rstrip("\r\n")
        newline = line[len(stripped):]
        assert stripped == stripped.rstrip(), f"trailing space in {path}:{lineno}"
        lines[lineno - 1] = stripped + " = None" + newline
    path.write_text("".join(lines), encoding="utf-8")
    changed_total += len(targets)
    print(f"{path}: {len(targets)} fields defaulted to None")

print("total:", changed_total)

