        return True
    if isinstance(annotation, ast.Subscript):
        head = annotation.value
        if isinstance(head, ast.Name) and head.id in ("Optional", "Union"):
            slice_ = annotation.slice
            args = slice_.elts if isinstance(slice_, ast.Tuple) else [slice_]
            return any(top_level_allows_none(arg) for arg in args)
    return False


